{
  "PROP-6a4369e9-inv-041": {
    "property_id": "PROP-6a4369e9-inv-041",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-041",
      "classification": "vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_column_verification.rs::from_execution_verified::L309-310",
      "proof_trace": "The execution layer path (engine_getBlobsV2 \u2192 from_execution_verified) skips KZG verification entirely, while gossip path performs verify_cell_kzg_proof_batch. Cached unverified columns then bypass gossip verification (L486-500), violating equivalence.",
      "attack_scenario": "Malicious EL provides invalid KZG proofs via engine_getBlobsV2. Consensus layer accepts and caches them without verification (from_execution_verified), then propagates them on gossip, bypassing KZG checks for cached columns. Network accepts invalid data availability proofs.",
      "checklist_id": "PROP-6a4369e9-inv-041"
    },
    "text": "Any optimized KZG verification path must produce same accept/reject as unoptimized batch verify.",
    "assertion": "forall input: optimized_kzg_verify(input) == verify_cell_kzg_proof_batch(input)",
    "covers": "SG-003",
    "severity": "CRITICAL",
    "type": "invariant"
  }
}

